/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export interface PromptVersion {
  id: string
  content: string
  savedAt: Date | number | string
  author?: string
  /** A short name, for example "Shorter refund policy". Defaults to "Version n". */
  label?: string
}

export interface SystemPromptEditorProps
  extends Omit<React.ComponentProps<"div">, "defaultValue" | "onChange" | "title" | "children"> {
  /** The saved prompt. The editor keeps its own draft until Save. */
  value?: string
  defaultValue?: string
  /** Every edit to the draft. */
  onDraftChange?: (draft: string) => void
  /** Save the draft. Cmd/Ctrl+S also saves. Return a promise to show Saving; throw to show the error. */
  onSave?: (content: string) => void | Promise<void>
  /** Saved versions, newest first. Restoring one loads it as an unsaved draft. */
  versions?: PromptVersion[]
  onRestore?: (version: PromptVersion) => void
  /** Token counter. Defaults to a four-characters-per-token estimate, shown with `≈`. */
  countTokens?: (text: string) => number
  /** Shows a meter: quiet below 80%, amber up to the budget, red past it. */
  tokenBudget?: number
  /** Show line numbers in a gutter. */
  lineNumbers?: boolean
  /**
   * Variables the prompt is rendered with. `{{name}}` placeholders not in the list get an amber
   * wavy underline. Leave unset to treat every placeholder as known.
   */
  variables?: string[]
  /** Default "System prompt". */
  title?: React.ReactNode
  placeholder?: string
  /** Height before the prompt scrolls inside. Default 360. */
  maxHeight?: number | string
  /** Default 160. */
  minHeight?: number | string
  readOnly?: boolean
  disabled?: boolean
}

/* -------------------------------------------------------------------------------------------------
 * SystemPromptEditor
 * -----------------------------------------------------------------------------------------------*/

/**
 * An editor for system prompts. A plain textarea sits over a highlighted copy of its text, so the
 * caret, selection, undo, spellcheck and IME composition are all native. `{{variables}}` are
 * tinted, unknown ones get a wavy underline, XML tags recede. Tokens are counted live against a
 * budget, saved versions can be restored, and Cmd/Ctrl+S saves.
 */
/** The clock once mounted; null while rendering, which must not read it (Next.js prerender). */
function useMountedNow() {
  const [now, setNow] = React.useState<number | null>(null)
  React.useEffect(() => setNow(Date.now()), [])
  return now
}

export type PromptSaveStatus = "idle" | "saving" | "saved" | "error"

/** Platform-aware shortcut label. */
function useModKey() {
  const [mac, setMac] = React.useState(true)
  React.useEffect(() => {
    setMac(/Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent))
  }, [])
  return mac ? "⌘" : "Ctrl"
}

/** Rough token count: about four characters per token for English prose and code. */
function estimateTokens(text: string): number {
  if (!text) return 0
  return Math.ceil(text.length / 4)
}

/**
 * Prompt template parsing for `{{variable}}` placeholders, shared by the system prompt editor and
 * the prompt template form. Dependency free and safe to run on every keystroke.
 *
 * Syntax:
 *   {{name}}            a variable
 *   {{ name }}          spaces inside the braces are ignored
 *   {{name:default}}    a variable with a default value (everything after the first colon)
 *
 * Names start with a letter or underscore and may contain letters, digits, `_`, `-` and `.`.
 * Anything else inside double braces is left as plain text.
 */

/** One `{{...}}` occurrence or a run of plain text. Offsets are into the source string. */
type TemplateSegment =
  | { type: "text"; text: string; start: number; end: number }
  | {
      type: "variable"
      /** The raw source, for example `{{tone:friendly}}`. */
      text: string
      name: string
      /** The text after the colon, when there is one. An empty default (`{{x:}}`) is `""`. */
      defaultValue?: string
      start: number
      end: number
    }

const VARIABLE = /\{\{\s*([A-Za-z_][\w.-]*)\s*(?::([^}]*))?\}\}/g

/** Split a template into text and variable segments, in order. */
function parseTemplate(source: string): TemplateSegment[] {
  const segments: TemplateSegment[] = []
  let last = 0
  for (const match of source.matchAll(VARIABLE)) {
    const start = match.index ?? 0
    const end = start + match[0].length
    if (start > last) {
      segments.push({ type: "text", text: source.slice(last, start), start: last, end: start })
    }
    segments.push({
      type: "variable",
      text: match[0],
      name: match[1] ?? "",
      ...(match[2] !== undefined ? { defaultValue: match[2].trim() } : {}),
      start,
      end,
    })
    last = end
  }
  if (last < source.length) {
    segments.push({ type: "text", text: source.slice(last), start: last, end: source.length })
  }
  return segments
}

