/** Copy swaps to a check with a 150 ms blur crossfade, holds for 1.5 s and announces itself. */
function CopyButton({
  value,
  label = "Copy",
  onCopy,
  onClick,
  children,
  size = "icon-sm",
  className,
  ...props
}: CopyButtonProps) {
  // A counter, not a flag: copying again while the check shows restarts the 1.5 s hold.
  const [copies, setCopies] = React.useState(0)
  const [copied, setCopied] = React.useState(false)
  React.useEffect(() => {
    if (!copies) return
    setCopied(true)
    const id = window.setTimeout(() => setCopied(false), 1500)
    return () => window.clearTimeout(id)
  }, [copies])

  // Reduced motion keeps the crossfade and drops the scale and blur.
  const layer = cn(
    "ease-(--chatcn-ease-out) absolute transition-[opacity,scale,filter] duration-150",
    "motion-reduce:scale-100 motion-reduce:blur-none motion-reduce:transition-opacity",
  )
  return (
    <Button
      {...props}
      size={size}
      aria-label={children ? undefined : copied ? "Copied" : label}
      onClick={(event) => {
        // Compose with handlers injected by wrappers such as Tooltip instead of replacing them.
        onClick?.(event)
        if (event.defaultPrevented) return
        const text = typeof value === "function" ? value() : value
        navigator.clipboard
          ?.writeText(text)
          .then(() => {
            setCopies((n) => n + 1)
            onCopy?.(text)
          })
          // Clipboard access can be denied (insecure context, permissions). Stay quiet and unchanged.
          .catch(() => {})
      }}
      className={cn("relative", className)}
    >
      {children ? (
        <>
          <span className="relative grid size-3.5 place-items-center">
            <CopyIcon
              className={cn(
                layer,
                copied ? "scale-75 opacity-0 blur-[2px]" : "scale-100 opacity-100",
              )}
            />
            <CheckIcon
              className={cn(
                layer,
                copied ? "scale-100 opacity-100" : "scale-75 opacity-0 blur-[2px]",
              )}
            />
          </span>
          {children}
        </>
      ) : null}
      {children ? null : (
        <>
          <CopyIcon
            className={cn(
              layer,
              copied ? "scale-75 opacity-0 blur-[2px]" : "scale-100 opacity-100",
            )}
          />
          <CheckIcon
            className={cn(
              layer,
              copied ? "scale-100 opacity-100" : "scale-75 opacity-0 blur-[2px]",
            )}
          />
        </>
      )}
      <span aria-live="polite" className="sr-only">
        {copied ? "Copied" : ""}
      </span>
    </Button>
  )
}

const TAG = /(<\/?[A-Za-z][\w-]*(?:\s[^<>]*)?\/?>)/g

/** Text runs inside a line: XML-style tags recede to gray, everything else is plain. */
function PlainRun({ text }: { text: string }) {
  if (!text.includes("<")) return <>{text}</>
  const parts = text.split(TAG)
  return (
    <>
      {parts.map((part, i) =>
        i % 2 === 1 ? (
          <span key={i} className="text-(color:--chatcn-fg-subtle)">
            {part}
          </span>
        ) : (
          <React.Fragment key={i}>{part}</React.Fragment>
        ),
      )}
    </>
  )
}

/**
 * The highlighted copy of one line. It must lay out exactly like the textarea: same font, size,
 * line height, padding and wrapping, and no change in weight or letter spacing on any run.
 */
function MirrorLine({ line, known }: { line: string; known: Set<string> | null }) {
  if (line === "") return <>{"​"}</>
  return (
    <>
      {parseTemplate(line).map((segment) => {
        if (segment.type === "text") return <PlainRun key={segment.start} text={segment.text} />
        const unknown = known !== null && !known.has(segment.name)
        return (
          <span
            key={segment.start}
            data-variable={segment.name}
            data-unknown={unknown ? "" : undefined}
            className={cn(
              "rounded-[3px]",
              unknown
                ? "bg-(color:--chatcn-amber-bg) text-(color:--chatcn-amber) decoration-(color:--chatcn-amber) underline decoration-wavy decoration-1 underline-offset-[3px]"
                : "bg-(color:--chatcn-blue-bg) text-(color:--chatcn-blue) shadow-[0_0_0_1px_var(--chatcn-blue-bg)]",
            )}
          >
            <span className="opacity-60">{"{{"}</span>
            {segment.text.slice(2, -2)}
            <span className="opacity-60">{"}}"}</span>
          </span>
        )
      })}
    </>
  )
}

/* -------------------------------------------------------------------------------------------------
 * Token meter
