function TokenMeter({
  count,
  budget,
  estimated,
}: {
  count: number
  budget?: number
  estimated: boolean
}) {
  const ratio = budget ? count / budget : 0
  const level = !budget ? "none" : ratio > 1 ? "over" : ratio >= 0.8 ? "near" : "ok"
  const label = `${estimated ? "About " : ""}${count.toLocaleString()} tokens${budget ? ` of ${budget.toLocaleString()}` : ""}`
  return (
    <span
      data-slot="system-prompt-tokens"
      data-token-level={level}
      className={cn(
        "text-[0.75rem]/[1rem] flex min-w-0 items-center gap-2 tabular-nums",
        level === "over"
          ? "text-(color:--chatcn-red)"
          : level === "near"
            ? "text-(color:--chatcn-amber)"
            : "text-(color:--chatcn-fg-subtle)",
