                : level === "near"
                  ? "bg-(color:--chatcn-amber)"
                  : "bg-(color:--chatcn-accent)",
            )}
            style={{ transform: `scaleX(${Math.min(1, ratio)})` }}
          />
        </span>
      ) : null}
      <span aria-hidden={budget ? true : undefined} dir="ltr" className="truncate">
        {estimated ? "≈ " : ""}
        {count.toLocaleString()}
        {budget ? ` / ${budget.toLocaleString()}` : ""} tokens
