export function SystemPromptEditor({
  value,
  defaultValue = "",
  onDraftChange,
  onSave,
  versions,
  onRestore,
  countTokens,
  tokenBudget,
  lineNumbers = false,
  variables,
  title = "System prompt",
  placeholder = "You are a support agent for a payments API. Answer in two short paragraphs…",
  maxHeight = 360,
  minHeight = 160,
  readOnly = false,
  disabled = false,
  className,
  id: idProp,
  ...props
}: SystemPromptEditorProps) {
  const now = useMountedNow()
  const autoId = React.useId()
  const id = idProp ?? autoId
  const [savedState, setSavedState] = React.useState(value ?? defaultValue)
  const saved = value ?? savedState
  const [draft, setDraftState] = React.useState(saved)
  const [status, setStatus] = React.useState<PromptSaveStatus>("idle")
  const [restored, setRestored] = React.useState<PromptVersion | null>(null)
  const savedTimer = React.useRef(0)
  const mod = useModKey()

  // A new saved value from outside replaces the draft only when there are no unsaved edits.
  const prevSaved = React.useRef(saved)
  React.useEffect(() => {
    if (prevSaved.current === saved) return
    const wasDirty = draft !== prevSaved.current
    prevSaved.current = saved
    if (!wasDirty) setDraftState(saved)
  }, [saved, draft])
  React.useEffect(() => () => window.clearTimeout(savedTimer.current), [])

  const setDraft = (next: string) => {
    setDraftState(next)
    onDraftChange?.(next)
    if (status === "saved" || status === "error") setStatus("idle")
  }

  const dirty = draft !== saved
  const editable = !readOnly && !disabled
  const canSave = dirty && editable && status !== "saving" && onSave !== undefined

  const save = async () => {
    if (!canSave) return
    setStatus("saving")
    try {
      await onSave?.(draft)
      if (value === undefined) setSavedState(draft)
      prevSaved.current = draft
      setRestored(null)
      setStatus("saved")
      window.clearTimeout(savedTimer.current)
      savedTimer.current = window.setTimeout(() => setStatus("idle"), 2000)
    } catch {
      setStatus("error")
    }
  }

  const tokens = React.useMemo(() => (countTokens ?? estimateTokens)(draft), [countTokens, draft])
  const lines = React.useMemo(() => draft.split("\n"), [draft])
  const known = React.useMemo(() => (variables ? new Set(variables) : null), [variables])
  const placeholders = React.useMemo(() => {
    const names = new Set<string>()
    for (const s of parseTemplate(draft)) if (s.type === "variable") names.add(s.name)
    return [...names]
  }, [draft])
  const unknownCount = known ? placeholders.filter((n) => !known.has(n)).length : 0
  const digits = String(lines.length).length
  const currentVersion = versions?.find((v) => v.content === saved)

  const size = (v: number | string) => (typeof v === "number" ? `${v}px` : v)

  const statusText =
    status === "saving"
      ? "Saving"
      : status === "saved"
        ? "Saved"
        : status === "error"
          ? "Couldn't save. Check your connection and press Save again."
          : restored && dirty
            ? `Restored ${restored.label ?? "an older version"}. Save to keep it.`
            : dirty
              ? "Unsaved changes"
              : null

  return (
    // biome-ignore lint/a11y/noStaticElementInteractions: Cmd/Ctrl+S bubbles up from the controls inside
    <div
      data-slot="system-prompt-editor"
      data-dirty={dirty ? "" : undefined}
      data-save-status={status}
      onKeyDown={(event) => {
        if (
          (event.metaKey || event.ctrlKey) &&
          !event.altKey &&
          event.key.toLowerCase() === "s" &&
          !event.nativeEvent.isComposing
        ) {
          event.preventDefault()
          void save()
        }
      }}
      className={cn(
        "rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) text-(color:--chatcn-fg) flex min-w-0 flex-col overflow-hidden",
        "forced-colors:outline-1 forced-colors:outline-solid",
        // Disabled sinks the card and steps the prompt down the gray ramp. No fade: every line
        // of text keeps its contrast.
        disabled && "bg-(color:--chatcn-bg-subtle) shadow-(--chatcn-shadow-border)",
        className,
      )}
      {...props}
    >
      {/* Header */}
      <div className="border-(color:--chatcn-border)/70 flex h-11 shrink-0 items-center gap-2 border-b ps-4 pe-2">
        <label htmlFor={id} className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] min-w-0 truncate font-medium">
          {title}
        </label>
        {readOnly ? (
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) shrink-0">Read only</span>
        ) : null}
        {placeholders.length > 0 ? (
          <span
            dir="ltr"
            className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) hidden shrink-0 tabular-nums sm:inline"
          >
            {placeholders.length} {placeholders.length === 1 ? "variable" : "variables"}
            {unknownCount > 0 ? (
              <span className="text-(color:--chatcn-amber)">, {unknownCount} unknown</span>
            ) : null}
          </span>
        ) : null}
        <span className="flex-1" />
        {versions && versions.length > 0 ? (
          <Menu>
            <MenuTrigger
              render={<Button size="sm" />}
              disabled={disabled}
              className="pointer-coarse:h-11"
            >
              <HistoryIcon />
              History
              <ChevronDownIcon className="text-(color:--chatcn-fg-subtle) -me-0.5" />
            </MenuTrigger>
            <MenuContent align="end" className="w-72">
              <MenuGroup>
                <MenuLabel>
                  {versions.length} saved {versions.length === 1 ? "version" : "versions"}
                </MenuLabel>
                {versions.map((version, index) => {
                  const current = version === currentVersion
                  const name = version.label ?? `Version ${versions.length - index}`
                  const date = toDate(version.savedAt)
                  return (
                    <MenuItem
                      key={version.id}
                      disabled={readOnly}
                      onClick={() => {
                        if (current && !dirty) return
                        setDraft(version.content)
                        setRestored({ ...version, label: name })
                        onRestore?.(version)
                      }}
                      className="items-start py-2"
                    >
                      <span className="flex min-w-0 flex-1 flex-col gap-0.5">
                        <span className="truncate">{name}</span>
                        <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) truncate tabular-nums">
                          <time dateTime={date.toISOString()}>
                            {relativeTime(date, now ?? date.getTime())}
                          </time>
                          {version.author ? ` · ${version.author}` : ""}
                        </span>
                      </span>
                      {current ? (
                        <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex shrink-0 items-center gap-1 pt-0.5">
                          <CheckIcon aria-hidden="true" className="size-3.5!" />
                          Current
                        </span>
                      ) : null}
                    </MenuItem>
                  )
                })}
              </MenuGroup>
            </MenuContent>
          </Menu>
        ) : null}
        <CopyButton
          size="icon-sm"
          label="Copy prompt"
          value={() => draft}
          disabled={draft === ""}
          className="pointer-coarse:size-11"
        />
      </div>

      {/* Editor: the textarea and its highlighted mirror share one scroll container. */}
      <div
        data-slot="system-prompt-scroll"
        className="chatcn-scroll relative overflow-y-auto overscroll-contain"
        style={{ maxHeight: size(maxHeight) }}
      >
        <div
          className="relative"
          style={
            {
              minHeight: size(minHeight),
              "--gutter": lineNumbers ? `calc(${Math.max(2, digits)}ch + 1.75rem)` : "0px",
            } as React.CSSProperties
          }
        >
          <div
            aria-hidden="true"
            data-slot="system-prompt-mirror"
            className={cn(
              "text-[0.8125rem]/[1.25rem] py-3 font-mono leading-5 select-none rtl:font-sans",
              disabled && "text-(color:--chatcn-fg-muted)",
            )}
          >
            {lines.map((line, index) => (
              <div key={index} className="flex">
                {lineNumbers ? (
                  <span className="text-(color:--chatcn-fg-subtle) w-(--gutter) shrink-0 ps-3 pe-3 text-end tabular-nums">
                    {index + 1}
                  </span>
                ) : null}
                <span
                  className={cn(
                    "min-w-0 flex-1 break-words whitespace-pre-wrap",
                    lineNumbers ? "ps-3 pe-4" : "px-4",
                  )}
                >
                  {draft === "" ? "​" : <MirrorLine line={line} known={known} />}
                </span>
              </div>
            ))}
          </div>
          {lineNumbers ? (
            <span
              aria-hidden="true"
              className="bg-(color:--chatcn-border)/60 pointer-events-none absolute inset-y-0 start-(--gutter) w-px"
            />
          ) : null}
          <textarea
            id={id}
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            readOnly={readOnly}
            disabled={disabled}
            placeholder={placeholder}
            spellCheck={false}
            autoComplete="off"
            aria-describedby={`${id}-status`}
            className={cn(
              "text-[0.8125rem]/[1.25rem] absolute inset-y-0 start-(--gutter) end-0 block h-full resize-none overflow-hidden bg-transparent py-3 font-mono leading-5 break-words whitespace-pre-wrap outline-none rtl:font-sans",
              lineNumbers ? "ps-3 pe-4" : "px-4",
              "caret-(color:--chatcn-fg) text-transparent",
              "placeholder:text-(color:--chatcn-fg-subtle)",
              "selection:bg-(color:--chatcn-accent)/20",
              "disabled:cursor-not-allowed",
            )}
          />
        </div>
      </div>

      {/* Footer */}
      <div className="border-(color:--chatcn-border)/70 flex min-h-11 shrink-0 flex-wrap items-center gap-x-3 gap-y-1 border-t py-1.5 ps-4 pe-2">
        <TokenMeter count={tokens} budget={tokenBudget} estimated={countTokens === undefined} />
        <span className="flex-1" />
        <p
          id={`${id}-status`}
          aria-live="polite"
          className={cn(
            "text-[0.75rem]/[1rem] flex min-w-0 items-center gap-1.5",
            status === "error"
              ? "text-(color:--chatcn-red)"
              : dirty
                ? "text-(color:--chatcn-fg-muted)"
                : "text-(color:--chatcn-fg-subtle)",
          )}
        >
          {status === "saved" ? (
            <CheckIcon
              aria-hidden="true"
              className="size-3.5 shrink-0 motion-safe:animate-[chatcn-swap_150ms_var(--chatcn-ease-out)]"
            />
          ) : dirty && status === "idle" ? (
            <span aria-hidden="true" className="bg-(color:--chatcn-fg) size-1.5 shrink-0 rounded-full" />
          ) : null}
          {statusText ? <span className="min-w-0 text-pretty">{statusText}</span> : null}
        </p>
        {onSave && !readOnly ? (
          <span className="flex shrink-0 items-center gap-1">
            {dirty && status !== "saving" ? (
              <Button
                size="sm"
                disabled={disabled}
                onClick={() => {
                  setDraft(saved)
                  setRestored(null)
                }}
                className="pointer-coarse:h-11"
              >
                Discard
              </Button>
            ) : null}
            <Button
              size="sm"
              variant="solid"
              disabled={!canSave}
              onClick={() => void save()}
              aria-keyshortcuts="Meta+S Control+S"
              className="min-w-[4.5rem] pe-1.5 pointer-coarse:h-11"
            >
