              Save
              <Kbd
                dir="ltr"
                className="bg-(color:--chatcn-primary-fg)/15 text-(color:--chatcn-primary-fg)/70 h-4 min-w-4 shadow-none"
              >
                {mod === "Ctrl" ? "Ctrl S" : "⌘S"}
              </Kbd>
            </Button>
          </span>
        ) : null}
      </div>
    </div>
  )
}

