const wait = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms))

/** Edit, then press Cmd/Ctrl+S. History restores any saved version as an unsaved draft. */
function SystemPromptEditorDemo() {
  const [saved, setSaved] = React.useState(supportPrompt)
  return (
    <SystemPromptEditor
      className="w-full max-w-2xl"
      value={saved}
      variables={supportVariables}
      versions={supportVersions}
      tokenBudget={400}
      onSave={async (next) => {
        await wait(600)
        setSaved(next)
      }}
    />
  )
}

